#include <plc.hpp>
// Hand-built diagnostic only: true timer options remain gated for SMBP export.
// Separate instances: retention and dynamic mode are never combined here.
plc::Ton retained_on{0, 1000, 20, true, false};
plc::Tof retained_off{1, 1000, 20, true, false};
plc::Ton dynamic_on{2, 1000, 20, false, true};

void scan() {
    bool ton_in = plc::input(0);
    bool tof_in = plc::input(1);
    bool dynamic_in = plc::input(2);
    bool request_five = plc::input(3);
    bool restore_twenty = plc::input(4);
    // Restore has explicit priority if both preset buttons are held.
    if (restore_twenty) {
        dynamic_on.set_preset(20);
    } else if (request_five) {
        dynamic_on.set_preset(5);
    }
    bool ton_q = retained_on.update(ton_in);
    bool tof_q = retained_off.update(tof_in);
    bool dynamic_q = dynamic_on.update(dynamic_in);

    plc::write_word(200, retained_on.value());
    plc::write_word(201, retained_on.preset());
    plc::write_word(202, retained_off.value());
    plc::write_word(203, retained_off.preset());
    plc::write_word(204, dynamic_on.value());
    plc::write_word(205, dynamic_on.preset());
    plc::output(0, ton_q);
    plc::output(1, tof_q);
    plc::output(2, dynamic_q);
    plc::output(3, ton_in);
    plc::output(4, tof_in);
    plc::output(5, dynamic_in);
    plc::output(6, request_five);
    plc::output(7, restore_twenty);
    plc::output(8, retained_on.value() >= 5);
    plc::output(9, retained_off.value() >= 5);
    plc::output(10, dynamic_on.value() >= 6);
    plc::output(11, dynamic_on.preset() == 5);
    plc::output(12, dynamic_on.preset() == 20);
    plc::output(13, retained_on.value() > 0);
    plc::output(14, retained_off.value() > 0);
    plc::output(15, dynamic_on.value() > 0);
}
